<?php include "auth.php"; include "../database.php"; if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['partner_name']);$c=trim($_POST['category']);$d=trim($_POST['description']);$disc=intval($_POST['discount']);$feat=isset($_POST['featured'])?1:0;$s=$conn->prepare("INSERT INTO partner(partner_name,category,description,discount,featured,status) VALUES(?,?,?,?,?,'Active')");$s->bind_param("sssii",$n,$c,$d,$disc,$feat);$s->execute();header("Location: partners.php");exit;}if(isset($_GET['delete'])){$id=intval($_GET['delete']);$s=$conn->prepare("DELETE FROM partner WHERE partner_id=?");$s->bind_param("i",$id);$s->execute();header("Location: partners.php");exit;}$r=$conn->query("SELECT * FROM partner ORDER BY partner_id DESC"); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Partners</title><link rel="stylesheet" href="../style.css"></head><body><main class="container"><h1>Partner Management</h1><a class="btn secondary" href="index.php">Dashboard</a><div class="form-box"><form method="POST"><input name="partner_name" placeholder="Partner name" required><input name="category" placeholder="Category" required><textarea name="description" placeholder="Description"></textarea><input type="number" name="discount" min="0" max="100" value="0"><label><input type="checkbox" name="featured"> Featured</label><button>Add Partner</button></form></div><table><tr><th>Name</th><th>Category</th><th>Discount</th><th>Featured</th><th>Action</th></tr><?php while($p=$r->fetch_assoc()):?><tr><td><?=htmlspecialchars($p['partner_name'])?></td><td><?=htmlspecialchars($p['category'])?></td><td><?=$p['discount']?>%</td><td><?=$p['featured']?'Yes':'No'?></td><td><a class="btn secondary" href="?delete=<?=$p['partner_id']?>" onclick="return confirm('Delete this partner?')">Delete</a></td></tr><?php endwhile;?></table></main></body></html>